mapper.select:
SELECT d.*, c.category_name FROM flowable_process_design d LEFT JOIN flowable_category c ON c.category_code = d.category AND c.deleted = 0 WHERE d.deleted = 0
AND d.design_code LIKE CONCAT('%', #{designCode}, '%')
AND design_name LIKE CONCAT('%', #{designName}, '%')
AND category = #{category}
AND status = #{status}
ORDER BY d.sort, d.id DESC
